using UnityEngine;
using LWS.TruckSports;
namespace LWS.TruckTerrierRacing {
// Bounded actual pose recording. Ghosts contain renderers/transforms only; never gameplay bodies.
public sealed class TerrierReplay:MonoBehaviour {
 public TerrierMatch match;public Transform[] ghosts;public ParticleSystem[] bursts;public int capacity=2200;public bool Playing{get;private set;}public float TimeCursor{get;private set;}public float Duration{get;private set;}public float PlaybackSpeed=1;public int Angle;public bool AutoAngles=true;public float DecisiveTime;readonly float[] jumps=new float[96];readonly int[] jumpCounts=new int[12];int segment;float jumpStart,jumpEnd;bool manualScrub;public float Age{get;private set;}
 struct Pose {public Vector3 position;public Quaternion rotation;}
 Pose[] roots,parts;Transform[][] sourceParts,ghostParts;int[] offsets;float[] times;int[] masks;int count,partCount;float nextSample;readonly float[] crashTime=new float[12];readonly Vector3[] crashPosition=new Vector3[12];readonly bool[] crashed=new bool[12];
 public void Initialize(){sourceParts=new Transform[12][];ghostParts=new Transform[12][];offsets=new int[12];partCount=0;for(int i=0;i<12;i++){if(match.appearanceBridge!=null)match.appearanceBridge.ReplayChannels(i,out sourceParts[i],out ghostParts[i]);else{sourceParts[i]=match.racers[i].truck.visuals.GetComponentsInChildren<Transform>(true);ghostParts[i]=ghosts[i].GetChild(0).GetComponentsInChildren<Transform>(true);}if(sourceParts[i].Length!=ghostParts[i].Length)throw new System.InvalidOperationException("Replay visual hierarchy differs");offsets[i]=partCount;partCount+=sourceParts[i].Length;}capacity=Mathf.Clamp(capacity,2200,2400);roots=new Pose[capacity*12];parts=new Pose[capacity*partCount];times=new float[capacity];masks=new int[capacity];}
 public void ResetRecord(){if(roots==null)Initialize();else if(match.appearanceBridge!=null){if(partCount!=12*38)throw new System.InvalidOperationException("Preserve Terrier fixed38 selected replay channels.");for(int i=0;i<12;i++)match.appearanceBridge.ReplayChannels(i,out sourceParts[i],out ghostParts[i]);}Playing=false;count=0;Duration=nextSample=0;System.Array.Clear(crashed,0,12);System.Array.Clear(jumpCounts,0,12);foreach(var g in ghosts)g.gameObject.SetActive(false);foreach(var fx in bursts)fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 public void RecordJump(int slot,float time){int index=jumpCounts[slot];if(index<8){jumps[slot*8+index]=time;jumpCounts[slot]++;}}
 public void Crash(int slot,float time,Vector3 p){if(crashed[slot])return;crashed[slot]=true;crashTime[slot]=time;crashPosition[slot]=p;}
 public void Record(float time,bool force=false){if(match.appearanceBridge!=null)match.appearanceBridge.TryRefreshWeatherMetadata();if(Playing||count>=capacity||!force&&time<nextSample)return;nextSample=time+.02f;int alive=0;for(int i=0;i<12;i++){var racer=match.racers[i];if(racer.Alive||racer.Creamed)alive|=1<<i;roots[count*12+i]=new Pose{position=racer.truck.body.position,rotation=racer.truck.body.rotation};for(int k=0;k<sourceParts[i].Length;k++){var t=sourceParts[i][k];parts[count*partCount+offsets[i]+k]=new Pose{position=t.localPosition,rotation=t.localRotation};}}match.wrecks?.Record(count);match.crowd.Record(count);masks[count]=alive;times[count]=time;count++;Duration=time;}
 public void Begin(){if(count<2)return;if(match.appearanceBridge!=null)match.appearanceBridge.RefreshAllMetadata();else for(int i=0;i<12;i++){var color=new MaterialPropertyBlock();color.SetColor("_BaseColor",match.setup.players[i].color);color.SetColor("_Color",match.setup.players[i].color);foreach(var renderer in ghosts[i].GetComponentsInChildren<Renderer>(true))if(renderer.name=="Cab")renderer.SetPropertyBlock(color);}match.wrecks?.BeginReplay();match.crowd.BeginReplay();Playing=true;TimeCursor=Age=0;PlaybackSpeed=1;Angle=segment=0;AutoAngles=true;manualScrub=false;int focus=match.HeatWinner>=0?match.HeatWinner:0;float eventTime=jumpCounts[focus]>0?jumps[focus*8+Mathf.Min(jumpCounts[focus]-1,1)]:Duration*.5f;jumpStart=Mathf.Clamp(eventTime-.7f,1.6f,Mathf.Max(1.6f,Duration-3));jumpEnd=Mathf.Min(Duration-2,eventTime+1.1f);foreach(var racer in match.racers){racer.truck.Power(false);racer.truck.body.isKinematic=true;racer.truck.body.detectCollisions=false;racer.truck.visuals.gameObject.SetActive(false);}Draw();}
 public bool Step(float dt){if(!Playing)return true;Age+=dt;float slow=Mathf.Abs(DecisiveTime-TimeCursor)<1.2f?.35f:1;TimeCursor+=dt*PlaybackSpeed*slow;if(!manualScrub){if(segment==0&&TimeCursor>1.5f){segment=1;TimeCursor=jumpStart;if(AutoAngles)Angle=1;}if(segment==1&&TimeCursor>=jumpEnd){segment=2;TimeCursor=Mathf.Max(TimeCursor,DecisiveTime-2.4f);if(AutoAngles)Angle=0;}}float end=!manualScrub&&segment==2?Mathf.Min(Duration,DecisiveTime+1.8f):Duration;TimeCursor=Mathf.Min(TimeCursor,end);Draw();return TimeCursor>=end&&Age>2||Age>(manualScrub&&!match.AllAI?35:12);}
 public void Seek(float time){manualScrub=true;TimeCursor=Mathf.Clamp(time,0,Duration);Draw();}
 public void Draw(){if(count<2)return;int lo=0,hi=count-1;while(lo+1<hi){int mid=(lo+hi)/2;if(times[mid]<=TimeCursor)lo=mid;else hi=mid;}float t=Mathf.InverseLerp(times[lo],times[hi],TimeCursor);for(int i=0;i<12;i++){bool visible=(masks[lo]&(1<<i))!=0;ghosts[i].gameObject.SetActive(visible);if(!visible)continue;var a=roots[lo*12+i];var b=roots[hi*12+i];ghosts[i].SetPositionAndRotation(Vector3.Lerp(a.position,b.position,t),Quaternion.Slerp(a.rotation,b.rotation,t));for(int k=0;k<ghostParts[i].Length;k++){a=parts[lo*partCount+offsets[i]+k];b=parts[hi*partCount+offsets[i]+k];ghostParts[i][k].SetLocalPositionAndRotation(Vector3.Lerp(a.position,b.position,t),Quaternion.Slerp(a.rotation,b.rotation,t));}}
 match.wrecks?.DrawReplay(lo,hi,t);match.crowd.DrawReplay(lo,hi,t);for(int i=0;i<bursts.Length;i++){var fx=bursts[i];if(i<12&&crashed[i]&&TimeCursor>=crashTime[i]&&TimeCursor-crashTime[i]<.8f){fx.gameObject.SetActive(true);fx.transform.position=crashPosition[i];fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);fx.useAutoRandomSeed=false;fx.randomSeed=(uint)(match.Seed+i*137);fx.Simulate(TimeCursor-crashTime[i],true,true,true);}else fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 match.course.weather.Tick(TimeCursor);
 }
 public Vector3 Focus {get{int slot=match.HeatWinner>=0?match.HeatWinner:0;return ghosts[slot].position;}}
 public void End(){match.wrecks?.EndReplay();match.crowd?.EndReplay();Playing=false;foreach(var g in ghosts)g.gameObject.SetActive(false);foreach(var fx in bursts)fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
}
}
